func PushTrailsBranch(remote string) error {
	if isTrailsDisabled() {
		return nil
	}
	return pushSessionsBranchCommon(remote, paths.TrailsBranchName)
}

// isTrailsDisabled checks if trails are disabled in settings.
// Returns true if strategy_options.trails is explicitly set to false.
func isTrailsDisabled() bool {
	s, err := settings.Load()
	if err != nil {
		return false // Default: trails enabled
	}
	return s.IsTrailsDisabled()
}

