106→func runTrailListAll(w io.Writer, statusFilter string, jsonOutput bool) error {
107→	// Fetch remote trails branch so we see trails from collaborators
108→	fetchTrailsBranch()
109→
110→	repo, err := strategy.OpenRepository()
111→	if err != nil {
112→		return fmt.Errorf("failed to open repository: %w", err)
113→	}
114→
115→	store := trail.NewStore(repo)
116→	trails, err := store.List()
117→	if err != nil {
118→		return fmt.Errorf("failed to list trails: %w", err)
119→	}
120→
121→	if trails == nil {
122→		trails = []*trail.Metadata{}
123→	}
124→
125→	// Apply status filter
126→	if statusFilter != "" {
127→		status := trail.Status(statusFilter)
128→		if !status.IsValid() {
129→			return fmt.Errorf("invalid status %q: valid values are %s", statusFilter, formatValidStatuses())
130→		}
131→		var filtered []*trail.Metadata
132→		for _, t := range trails {
133→			if t.Status == status {
134→				filtered = append(filtered, t)
135→			}
136→		}
137→		trails = filtered
138→	}
139→
140→	// Sort by updated_at descending
141→	sort.Slice(trails, func(i, j int) bool {
142→		return trails[i].UpdatedAt.After(trails[j].UpdatedAt)
143→	})
144→
145→	if jsonOutput {
146→		enc := json.NewEncoder(w)
147→		enc.SetIndent("", "  ")
148→		if err := enc.Encode(trails); err != nil {
149→			return fmt.Errorf("failed to encode JSON: %w", err)
150→		}
151→		return nil
152→	}
153→
154→	if len(trails) == 0 {
155→		fmt.Fprintln(w, "No trails found.")
156→		fmt.Fprintln(w)
157→		fmt.Fprintln(w, "Commands:")
158→		fmt.Fprintln(w, "  entire trail create   Create a trail for the current branch")
159→		fmt.Fprintln(w, "  entire trail list     List all trails")
160→		fmt.Fprintln(w, "  entire trail update   Update trail metadata")
161→		return nil
162→	}
163→
164→	// Table output
165→	fmt.Fprintf(w, "%-30s %-40s %-13s %-15s %s\n", "BRANCH", "TITLE", "STATUS", "AUTHOR", "UPDATED")
166→	for _, t := range trails {
167→		branch := truncate(t.Branch, 30)
168→		title := truncate(t.Title, 40)
169→		fmt.Fprintf(w, "%-30s %-40s %-13s %-15s %s\n",
170→			branch, title, t.Status, truncate(t.Author, 15), timeAgo(t.UpdatedAt))
171→	}
172→
173→	return nil
174→}
