504→// titleFromPrompt extracts a trail title from the user's prompt.
505→// Uses the first line, trimmed and truncated to 80 characters.
506→// Returns empty string if prompt is empty.
507→func titleFromPrompt(prompt string) string {
508→	if prompt == "" {
509→		return ""
510→	}
511→	line, _, _ := strings.Cut(prompt, "\n")
512→	title := strings.TrimSpace(line)
513→	if len(title) > 80 {
514→		title = title[:77] + "..."
515→	}
516→	return title
517→}
