519→// hasFlag is a simple helper that checks os.Args for --flag presence.
520→// Used to distinguish between "flag not provided" and "flag provided with empty value".
521→func hasFlag(name string) bool {
522→	for _, arg := range os.Args {
523→		if arg == "--"+name || strings.HasPrefix(arg, "--"+name+"=") {
524→			return true
525→		}
526→	}
527→	return false
528→}
