530→func truncate(s string, maxLen int) string {
531→	if len(s) <= maxLen {
532→		return s
533→	}
534→	if maxLen <= 3 {
535→		return s[:maxLen]
536→	}
537→	return s[:maxLen-3] + "..."
538→}
