540→func formatValidStatuses() string {
541→	statuses := trail.ValidStatuses()
542→	names := make([]string, len(statuses))
543→	for i, s := range statuses {
544→		names[i] = string(s)
545→	}
546→	return strings.Join(names, ", ")
547→}
