549→func containsString(slice []string, s string) bool {
550→	for _, v := range slice {
551→		if v == s {
552→			return true
553→		}
554→	}
555→	return false
556→}
557→
558→func removeString(slice []string, s string) []string {
559→	var result []string
560→	for _, v := range slice {
561→		if v != s {
562→			result = append(result, v)
563→		}
564→	}
565→	return result
566→}
