596→	var statusOptions []huh.Option[string]
597→	for _, s := range trail.ValidStatuses() {
598→		if s == trail.StatusDone || s == trail.StatusClosed {
599→			continue
600→		}
601→		statusOptions = append(statusOptions, huh.NewOption(string(s), string(s)))
602→	}
603→	if *statusStr == "" {
604→		*statusStr = string(trail.StatusDraft)
605→	}
606→
607→	form = NewAccessibleForm(
608→		huh.NewGroup(
609→			huh.NewInput().
610→				Title("Branch name").
611→				Placeholder(suggested).
612→				Value(branch),
613→			huh.NewSelect[string]().
614→				Title("Status").
615→				Options(statusOptions...).
616→				Value(statusStr),
617→		),
618→	)
619→	if err := form.Run(); err != nil {
620→		return fmt.Errorf("form cancelled: %w", err)
621→	}
622→	*branch = strings.TrimSpace(*branch)
623→	if *branch == "" {
624→		*branch = suggested
625→	}
626→	return nil
627→}
