629→// fetchTrailsBranch fetches the remote trails branch so we see trails from collaborators.
630→// Best-effort: silently ignores errors (e.g., no remote, no network).
631→func fetchTrailsBranch() {
632→	ctx, cancel := context.WithTimeout(context.Background(), 10*time.Second)
633→	defer cancel()
634→	branchName := paths.TrailsBranchName
635→	refSpec := fmt.Sprintf("+refs/heads/%s:refs/remotes/origin/%s", branchName, branchName)
636→	//nolint:gosec // G204: branchName is a constant from paths package
637→	cmd := exec.CommandContext(ctx, "git", "fetch", "origin", refSpec)
638→	_ = cmd.Run() //nolint:errcheck // best-effort fetch
639→}
