656→// slugifyTitle converts a title string into a branch-friendly slug.
657→// Example: "Add user authentication" -> "add-user-authentication"
658→func slugifyTitle(title string) string {
659→	s := strings.ToLower(strings.TrimSpace(title))
660→	// Replace spaces and underscores with hyphens
661→	s = strings.NewReplacer(" ", "-", "_", "-").Replace(s)
662→	// Remove anything that's not alphanumeric, hyphen, or slash
663→	var b strings.Builder
664→	prevHyphen := false
665→	for _, r := range s {
666→		if (r >= 'a' && r <= 'z') || (r >= '0' && r <= '9') || r == '/' {
667→			b.WriteRune(r)
668→			prevHyphen = false
669→		} else if r == '-' && !prevHyphen {
670→			b.WriteRune('-')
671→			prevHyphen = true
672→		}
673→	}
674→	return strings.Trim(b.String(), "-")
675→}
