677→// branchNeedsCreation checks if a branch exists locally.
678→func branchNeedsCreation(repo *git.Repository, branchName string) bool {
679→	_, err := repo.Reference(plumbing.NewBranchReferenceName(branchName), true)
680→	return err != nil
681→}
