683→// createBranch creates a new local branch pointing at HEAD without checking it out.
684→func createBranch(repo *git.Repository, branchName string) error {
685→	head, err := repo.Head()
686→	if err != nil {
687→		return fmt.Errorf("failed to get HEAD: %w", err)
688→	}
689→	ref := plumbing.NewHashReference(plumbing.NewBranchReferenceName(branchName), head.Hash())
690→	if err := repo.Storer.SetReference(ref); err != nil {
691→		return fmt.Errorf("failed to create branch ref: %w", err)
692→	}
693→	return nil
694→}
