696→// pushBranchToOrigin pushes a branch to the origin remote.
697→func pushBranchToOrigin(branchName string) error {
698→	ctx, cancel := context.WithTimeout(context.Background(), 2*time.Minute)
699→	defer cancel()
700→	cmd := exec.CommandContext(ctx, "git", "push", "--no-verify", "-u", "origin", branchName)
701→	if output, err := cmd.CombinedOutput(); err != nil {
702→		return fmt.Errorf("%s: %w", strings.TrimSpace(string(output)), err)
703→	}
704→	return nil
705→}
