351→// getBranchTree returns the tree for the entire/trails branch HEAD.
352→func (s *Store) getBranchTree() (*object.Tree, error) {
353→	refName := plumbing.NewBranchReferenceName(paths.TrailsBranchName)
354→	ref, err := s.repo.Reference(refName, true)
355→	if err != nil {
356→		// Try remote tracking branch
357→		remoteRefName := plumbing.NewRemoteReferenceName("origin", paths.TrailsBranchName)
358→		ref, err = s.repo.Reference(remoteRefName, true)
359→		if err != nil {
360→			return nil, fmt.Errorf("trails branch not found: %w", err)
361→		}
362→	}
363→
364→	commit, err := s.repo.CommitObject(ref.Hash())
365→	if err != nil {
366→		return nil, fmt.Errorf("failed to get commit: %w", err)
367→	}
368→
369→	tree, err := commit.Tree()
370→	if err != nil {
371→		return nil, fmt.Errorf("failed to get tree: %w", err)
372→	}
373→
374→	return tree, nil
375→}
376→
377→// getBranchEntries returns the current branch reference and a flat map of all tree entries.
378→func (s *Store) getBranchEntries() (*plumbing.Reference, map[string]object.TreeEntry, error) {
379→	refName := plumbing.NewBranchReferenceName(paths.TrailsBranchName)
380→	ref, err := s.repo.Reference(refName, true)
381→	if err != nil {
382→		return nil, nil, fmt.Errorf("trails branch not found: %w", err)
383→	}
384→
385→	commit, err := s.repo.CommitObject(ref.Hash())
386→	if err != nil {
387→		return nil, nil, fmt.Errorf("failed to get commit: %w", err)
388→	}
389→
390→	tree, err := commit.Tree()
391→	if err != nil {
392→		return nil, nil, fmt.Errorf("failed to get tree: %w", err)
393→	}
394→
395→	entries := make(map[string]object.TreeEntry)
396→	if err := checkpoint.FlattenTree(s.repo, tree, "", entries); err != nil {
397→		return nil, nil, fmt.Errorf("failed to flatten tree: %w", err)
398→	}
399→
400→	return ref, entries, nil
401→}
402→
403→// createCommit creates a commit on the trails branch.
404→func (s *Store) createCommit(treeHash, parentHash plumbing.Hash, message, authorName, authorEmail string) (plumbing.Hash, error) {
405→	now := time.Now()
406→	sig := object.Signature{
407→		Name:  authorName,
408→		Email: authorEmail,
409→		When:  now,
410→	}
411→
412→	commit := &object.Commit{
413→		TreeHash:  treeHash,
414→		Author:    sig,
415→		Committer: sig,
416→		Message:   message,
417→	}
418→
419→	if parentHash != plumbing.ZeroHash {
420→		commit.ParentHashes = []plumbing.Hash{parentHash}
421→	}
422→
423→	obj := s.repo.Storer.NewEncodedObject()
424→	if err := commit.Encode(obj); err != nil {
425→		return plumbing.ZeroHash, fmt.Errorf("failed to encode commit: %w", err)
426→	}
427→
428→	hash, err := s.repo.Storer.SetEncodedObject(obj)
429→	if err != nil {
430→		return plumbing.ZeroHash, fmt.Errorf("failed to store commit: %w", err)
431→	}
432→
433→	return hash, nil
434→}
