108→func runTrailListAll(w io.Writer, statusFilter string, jsonOutput bool) error {
109→	// Fetch remote trails branch so we see trails from collaborators
110→	fetchTrailsBranch()
111→
112→	repo, err := strategy.OpenRepository(context.Background())
113→	if err != nil {
114→		return fmt.Errorf("failed to open repository: %w", err)
115→	}
116→
117→	store := trail.NewStore(repo)
118→	trails, err := store.List()
119→	if err != nil {
120→		return fmt.Errorf("failed to list trails: %w", err)
121→	}
122→
123→	if trails == nil {
124→		trails = []*trail.Metadata{}
125→	}
126→
127→	// Apply status filter
128→	if statusFilter != "" {
129→		status := trail.Status(statusFilter)
130→		if !status.IsValid() {
131→			return fmt.Errorf("invalid status %q: valid values are %s", statusFilter, formatValidStatuses())
132→		}
133→		var filtered []*trail.Metadata
134→		for _, t := range trails {
135→			if t.Status == status {
136→				filtered = append(filtered, t)
137→			}
138→		}
139→		trails = filtered
140→	}
141→
142→	// Sort by updated_at descending
143→	sort.Slice(trails, func(i, j int) bool {
144→		return trails[i].UpdatedAt.After(trails[j].UpdatedAt)
145→	})
146→
147→	if jsonOutput {
148→		enc := json.NewEncoder(w)
149→		enc.SetIndent("", "  ")
150→		if err := enc.Encode(trails); err != nil {
151→			return fmt.Errorf("failed to encode JSON: %w", err)
152→		}
153→		return nil
154→	}
155→
156→	if len(trails) == 0 {
157→		fmt.Fprintln(w, "No trails found.")
158→		fmt.Fprintln(w)
159→		fmt.Fprintln(w, "Commands:")
160→		fmt.Fprintln(w, "  entire trail create   Create a trail for the current branch")
161→		fmt.Fprintln(w, "  entire trail list     List all trails")
162→		fmt.Fprintln(w, "  entire trail update   Update trail metadata")
163→		return nil
164→	}
165→
166→	// Table output
167→	fmt.Fprintf(w, "%-30s %-40s %-13s %-15s %s\n", "BRANCH", "TITLE", "STATUS", "AUTHOR", "UPDATED")
168→	for _, t := range trails {
169→		branch := truncate(t.Branch, 30)
170→		title := truncate(t.Title, 40)
171→		fmt.Fprintf(w, "%-30s %-40s %-13s %-15s %s\n",
172→			branch, title, t.Status, truncate(t.Author, 15), timeAgo(t.UpdatedAt))
173→	}
174→
175→	return nil
176→}
