510→// titleFromPrompt extracts a trail title from the user's prompt.
511→// Uses the first line, trimmed and truncated to 80 characters.
512→// Returns empty string if prompt is empty.
513→func titleFromPrompt(prompt string) string {
514→	if prompt == "" {
515→		return ""
516→	}
517→	line, _, _ := strings.Cut(prompt, "\n")
518→	title := strings.TrimSpace(line)
519→	if len(title) > 80 {
520→		title = title[:77] + "..."
521→	}
522→	return title
523→}
524→
525→// hasFlag is a simple helper that checks os.Args for --flag presence.
526→// Used to distinguish between "flag not provided" and "flag provided with empty value".
527→func hasFlag(name string) bool {
528→	for _, arg := range os.Args {
529→		if arg == "--"+name || strings.HasPrefix(arg, "--"+name+"=") {
530→			return true
531→		}
532→	}
533→	return false
534→}
535→
536→func truncate(s string, maxLen int) string {
537→	if len(s) <= maxLen {
538→		return s
539→	}
540→	if maxLen <= 3 {
541→		return s[:maxLen]
542→	}
543→	return s[:maxLen-3] + "..."
544→}
545→
546→func formatValidStatuses() string {
547→	statuses := trail.ValidStatuses()
548→	names := make([]string, len(statuses))
549→	for i, s := range statuses {
550→		names[i] = string(s)
551→	}
552→	return strings.Join(names, ", ")
553→}
554→
555→func containsString(slice []string, s string) bool {
556→	for _, v := range slice {
557→		if v == s {
558→			return true
559→		}
560→	}
561→	return false
562→}
563→
564→func removeString(slice []string, s string) []string {
565→	var result []string
566→	for _, v := range slice {
567→		if v != s {
568→			result = append(result, v)
569→		}
570→	}
571→	return result
572→}
