635→// fetchTrailsBranch fetches the remote trails branch so we see trails from collaborators.
636→// Best-effort: silently ignores errors (e.g., no remote, no network).
637→func fetchTrailsBranch() {
638→	ctx, cancel := context.WithTimeout(context.Background(), 10*time.Second)
639→	defer cancel()
