665→// slugifyTitle converts a title string into a branch-friendly slug.
666→// Example: "Add user authentication" -> "add-user-authentication"
667→func slugifyTitle(title string) string {
668→	s := strings.ToLower(strings.TrimSpace(title))
669→	// Replace spaces and underscores with hyphens
670→	s = strings.NewReplacer(" ", "-", "_", "-").Replace(s)
671→	// Remove anything that's not alphanumeric, hyphen, or slash
672→	var b strings.Builder
673→	prevHyphen := false
674→	for _, r := range s {
675→		if (r >= 'a' && r <= 'z') || (r >= '0' && r <= '9') || r == '/' {
676→			b.WriteRune(r)
677→			prevHyphen = false
678→		} else if r == '-' && !prevHyphen {
679→			b.WriteRune('-')
680→			prevHyphen = true
681→		}
682→	}
683→	return strings.Trim(b.String(), "-")
684→}
