692→// createBranch creates a new local branch pointing at HEAD without checking it out.
693→func createBranch(repo *git.Repository, branchName string) error {
694→	head, err := repo.Head()
695→	if err != nil {
696→		return fmt.Errorf("failed to get HEAD: %w", err)
697→	}
698→	ref := plumbing.NewHashReference(plumbing.NewBranchReferenceName(branchName), head.Hash())
699→	if err := repo.Storer.SetReference(ref); err != nil {
700→		return fmt.Errorf("failed to create branch ref: %w", err)
701→	}
702→	return nil
703→}
